use crate::repository::{Database,rows,err};
use rusqlite::{Connection,OptionalExtension,params};
use serde_json::{Value,json};
pub(crate) fn deleted(status:&str)->bool{["deleted","legacy:2"].contains(&status)}
pub(crate) fn tables(c:&Connection)->Result<(),String>{c.execute_batch("CREATE TABLE IF NOT EXISTS study_deletions(study_id INTEGER PRIMARY KEY,previous_status TEXT NOT NULL);CREATE TABLE IF NOT EXISTS bundle_state(bundle_id INTEGER PRIMARY KEY REFERENCES study_bundles(id),deleted INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1,origin TEXT NOT NULL DEFAULT 'native');CREATE TABLE IF NOT EXISTS bundle_item_revisions(bundle_id INTEGER NOT NULL,study_id INTEGER NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(bundle_id,study_id));CREATE TABLE IF NOT EXISTS legacy_bundle_map(source_id INTEGER PRIMARY KEY,bundle_id INTEGER NOT NULL UNIQUE REFERENCES study_bundles(id));").map_err(err)}
pub(crate) fn exists(c:&Connection,name:&str)->Result<bool,String>{Ok(c.query_row("SELECT count(*) FROM sqlite_master WHERE type='table' AND name=?",[name],|r|r.get::<_,i64>(0)).map_err(err)?>0)}
impl Database{
 pub(crate) fn migrate_lifecycle(&self,c:&Connection)->Result<(),String>{
  if c.query_row("SELECT value FROM metadata WHERE key='lifecycle_v1'",[],|r|r.get::<_,String>(0)).optional().map_err(err)?.is_some(){return Ok(())}
  let backup=self.backup()?;let tx=c.unchecked_transaction().map_err(err)?;tables(&tx)?;
  tx.execute("INSERT OR IGNORE INTO bundle_state(bundle_id) SELECT id FROM study_bundles",[]).map_err(err)?;
  tx.execute("INSERT OR IGNORE INTO bundle_item_revisions SELECT i.bundle_id,i.study_id,s.revision FROM bundle_items i JOIN studies s ON s.id=i.study_id",[]).map_err(err)?;
  let mut imported=0;let mut links=0;
  if exists(&tx,"legacy_container")?&&exists(&tx,"legacy_research")?{
   // ProtocolHandler uses ORDER BY protocol_id; source tables are never updated.
   for b in rows(&tx,"SELECT id,create_date,pacient_id FROM legacy_container ORDER BY id",[])?{
    let source=b["id"].as_i64().ok_or("Неверный ID старого комплекта")?;
    if tx.query_row("SELECT bundle_id FROM legacy_bundle_map WHERE source_id=?",[source],|r|r.get::<_,i64>(0)).optional().map_err(err)?.is_some(){continue}
    let patient=b["pacient_id"].as_i64().ok_or("Неверный пациент старого комплекта")?;let valid:i64=tx.query_row("SELECT count(*) FROM patients WHERE id=?",[patient],|r|r.get(0)).map_err(err)?;
    if valid!=1{return Err(format!("Старый комплект №{source}: пациент не найден. Исходные связи сохранены."))}
    let raw=tx.query_row("SELECT name FROM legacy_container WHERE id=?",[source],|r|Ok(crate::records::book_text(r.get_ref(0)?))).map_err(err)?;
    tx.execute("INSERT INTO study_bundles(patient_id,name,created_at) VALUES(?,?,?)",params![patient,if raw.trim().is_empty(){format!("Архивный комплект №{source}")}else{raw},b["create_date"].as_str().unwrap_or("")]).map_err(err)?;let id=tx.last_insert_rowid();
    tx.execute("INSERT INTO bundle_state(bundle_id,origin) VALUES(?,'legacy')",[id]).map_err(err)?;
    for (position,item) in rows(&tx,"SELECT protocol_id FROM legacy_research WHERE container_id=? ORDER BY protocol_id,id",[source])?.iter().enumerate(){
     let study=item["protocol_id"].as_i64().ok_or("Неверная ссылка старого комплекта")?;let row=rows(&tx,"SELECT patient_id,revision FROM studies WHERE id=?",[study])?.pop().ok_or(format!("Старый комплект №{source}: исследование №{study} отсутствует. Исходные связи сохранены."))?;
     if row["patient_id"]!=patient{return Err(format!("Старый комплект №{source}: пациент исследования №{study} не совпадает."))}
     tx.execute("INSERT INTO bundle_items VALUES(?,?,?)",params![id,study,position as i64]).map_err(err)?;tx.execute("INSERT INTO bundle_item_revisions VALUES(?,?,?)",params![id,study,row["revision"].as_i64()]).map_err(err)?;links+=1;
    }
    tx.execute("INSERT INTO legacy_bundle_map VALUES(?,?)",params![source,id]).map_err(err)?;imported+=1;
   }
  }
  let report=json!({"backup":backup,"bundles":imported,"links":links});tx.execute("INSERT INTO metadata VALUES('lifecycle_v1',?)",[report.to_string()]).map_err(err)?;tx.execute("INSERT INTO access_audit(action,details) VALUES('migrate_bundles',?)",[report.to_string()]).map_err(err)?;tx.commit().map_err(err)
 }
 pub fn set_study_deleted(&self,id:i64,revision:i64,remove:bool)->Result<(),String>{
  let mut c=self.open()?;let tx=c.transaction().map_err(err)?;let previous=rows(&tx,"SELECT * FROM studies WHERE id=?",[id])?.pop().ok_or("Исследование не найдено")?;
  if previous["revision"]!=revision{return Err("Исследование изменилось. Откройте его заново.".into())}let status=previous["status"].as_str().unwrap_or("");if deleted(status)==remove{return Err("Состояние исследования уже изменилось. Откройте его заново.".into())}tables(&tx)?;
  let next=if remove{tx.execute("INSERT INTO study_deletions VALUES(?,?) ON CONFLICT(study_id) DO UPDATE SET previous_status=excluded.previous_status",params![id,status]).map_err(err)?;"deleted".to_string()}else{tx.query_row("SELECT previous_status FROM study_deletions WHERE study_id=?",[id],|r|r.get::<_,String>(0)).optional().map_err(err)?.filter(|s|!deleted(s)).unwrap_or("draft".into())};
  tx.execute("UPDATE studies SET status=?,revision=revision+1,updated_at=datetime('now') WHERE id=? AND revision=?",params![next,id,revision]).map_err(err)?;tx.execute("INSERT INTO audit(entity,entity_id,previous_json,saved_at) VALUES('study',?,?,datetime('now'))",params![id,previous.to_string()]).map_err(err)?;crate::security::audit(&tx,if remove{"delete_study"}else{"restore_study"},id)?;tx.commit().map_err(err)
 }
 pub(crate) fn bundle_state(c:&Connection,id:i64)->Result<Value,String>{if exists(c,"bundle_state")?{if let Some(v)=rows(c,"SELECT deleted,revision,origin FROM bundle_state WHERE bundle_id=?",[id])?.pop(){return Ok(json!({"deleted":v["deleted"]==1,"revision":v["revision"],"origin":v["origin"]}))}}Ok(json!({"deleted":false,"revision":1,"origin":"native"}))}
 pub fn set_bundle_deleted(&self,id:i64,revision:i64,remove:bool)->Result<(),String>{let mut c=self.open()?;let tx=c.transaction().map_err(err)?;let _=tx.query_row("SELECT id FROM study_bundles WHERE id=?",[id],|r|r.get::<_,i64>(0)).map_err(err)?;let previous=Self::bundle_state(&tx,id)?;if previous["revision"]!=revision||previous["deleted"]==remove{return Err("Комплект изменился. Откройте его заново.".into())}tables(&tx)?;tx.execute("INSERT INTO bundle_state(bundle_id,deleted,revision,origin) VALUES(?,?,?,?) ON CONFLICT(bundle_id) DO UPDATE SET deleted=excluded.deleted,revision=excluded.revision",params![id,remove,revision+1,previous["origin"].as_str()]).map_err(err)?;tx.execute("INSERT INTO audit(entity,entity_id,previous_json,saved_at) VALUES('bundle',?,?,datetime('now'))",params![id,previous.to_string()]).map_err(err)?;crate::security::audit(&tx,if remove{"delete_bundle"}else{"restore_bundle"},id)?;tx.commit().map_err(err)}
 pub fn validate_bundle_print(&self,id:i64,revision:i64,expected:Vec<[i64;2]>)->Result<(),String>{let detail=self.bundle(id)?;if detail["bundle"]["revision"]!=revision||detail["canPrint"]!=true{return Err("Комплект недоступен для печати. Проверьте его состав.".into())}let actual:Vec<[i64;2]>=detail["studies"].as_array().unwrap().iter().map(|s|[s["id"].as_i64().unwrap(),s["revision"].as_i64().unwrap()]).collect();if actual!=expected{return Err("Исследования изменились после открытия. Обновите предпросмотр и проверьте документ.".into())}Ok(())}
}

#[cfg(test)]mod tests{
 use super::*;
 fn fixture()->Database{let root=std::env::temp_dir().join(format!("uzi-lifecycle-{}",chrono::Utc::now().timestamp_nanos_opt().unwrap()));std::fs::create_dir_all(&root).unwrap();let db=Database::new(root.join("uzi.db"));let c=Connection::open(&db.path).unwrap();c.execute_batch(include_str!("../schema.sql")).unwrap();c.execute_batch(include_str!("../extended.sql")).unwrap();c.execute_batch("PRAGMA user_version=2;INSERT INTO patients(id,name,search_name,gender) VALUES(1,'Тест','тест','F'),(2,'Другой','другой','M');INSERT INTO doctors VALUES(1,'Врач',0),(2,'Другой врач',0);INSERT INTO templates VALUES(1,'УЗИ','universal');INSERT INTO studies(id,patient_id,date,template_id,doctor_id,title,conclusion,addition,fields_json,origin,status) VALUES(1,1,'2026-11-08',1,1,'УЗИ','Первый','','{}','native','final'),(2,1,'2026-11-08',1,1,'УЗИ','Второй','','{}','legacy','legacy:1'),(3,2,'2026-11-08',1,2,'УЗИ','Другой','','{}','native','final'),(4,1,'2026-11-08',1,2,'УЗИ','Удалённый архив','','{}','legacy','legacy:2'),(5,1,'2026-11-08',1,1,'УЗИ','','','{}','native','draft'),(6,1,'2026-11-08',1,1,'УЗИ','Архивный черновик','','{}','legacy','legacy:0');CREATE TABLE legacy_container(id,create_date,pacient_id,name);CREATE TABLE legacy_research(id,container_id,protocol_id);").unwrap();for id in 1..=5{c.execute("INSERT INTO legacy_container VALUES(?,'2013-01-01',1,?)",params![id,format!("Старый комплект {id}")]).unwrap();c.execute("INSERT INTO legacy_research VALUES(?,?,2)",params![id*2-1,id]).unwrap();c.execute("INSERT INTO legacy_research VALUES(?,?,1)",params![id*2,id]).unwrap();}db}
 fn clean(db:Database){std::fs::remove_dir_all(db.path.parent().unwrap()).unwrap()}
 #[test]fn deletion_restoration_filters_and_edit_guard_preserve_all_original_fields(){let db=fixture();db.set_study_deleted(1,1,true).unwrap();assert_eq!(db.study(1).unwrap()["status"],"deleted");assert_eq!(db.study(1).unwrap()["conclusion"],"Первый");assert_eq!(db.studies_filtered("",0,50,"deleted").unwrap()["total"],2);assert_eq!(db.studies_filtered("",0,50,"active").unwrap()["total"],4);assert_eq!(db.studies_filtered("",0,50,"draft").unwrap()["total"],2);assert!(db.studies_filtered("",0,50,"DROP").is_err());assert!(db.set_study_deleted(1,1,false).unwrap_err().contains("изменилось"));let input=serde_json::from_value(json!({"id":1,"revision":2,"patientId":1,"templateId":1,"doctorId":1,"date":"2026-11-08","conclusion":"Обход удаления","addition":"","fields":{},"status":"final"})).unwrap();assert!(db.save_study(input).unwrap_err().contains("восстановить"));db.set_study_deleted(1,2,false).unwrap();assert_eq!(db.study(1).unwrap()["status"],"final");db.set_study_deleted(4,1,false).unwrap();assert_eq!(db.study(4).unwrap()["status"],"draft");assert_eq!(db.study(4).unwrap()["origin"],"legacy");clean(db)}
 #[test]fn five_legacy_bundles_and_ten_links_migrate_once_in_source_order(){let db=fixture();let c=db.open().unwrap();db.migrate_lifecycle(&c).unwrap();db.migrate_lifecycle(&c).unwrap();let report:String=c.query_row("SELECT value FROM metadata WHERE key='lifecycle_v1'",[],|r|r.get(0)).unwrap();let report:Value=serde_json::from_str(&report).unwrap();assert_eq!(report["bundles"],5);assert_eq!(report["links"],10);assert!(std::path::Path::new(report["backup"].as_str().unwrap()).is_file());assert_eq!(c.query_row("SELECT count(*) FROM study_bundles",[],|r|r.get::<_,i64>(0)).unwrap(),5);assert_eq!(c.query_row("SELECT count(*) FROM bundle_items",[],|r|r.get::<_,i64>(0)).unwrap(),10);assert_eq!(c.query_row("SELECT count(*) FROM legacy_research",[],|r|r.get::<_,i64>(0)).unwrap(),10);let detail=db.bundle(1).unwrap();assert_eq!(detail["bundle"]["origin"],"legacy");assert_eq!(detail["studies"][0]["id"],1);assert_eq!(detail["studies"][1]["id"],2);assert_eq!(detail["canPrint"],true);drop(c);clean(db)}
 #[test]fn invalid_legacy_links_abort_the_migration_without_partial_import(){let db=fixture();let c=db.open().unwrap();c.execute("UPDATE legacy_research SET protocol_id=3 WHERE id=10",[]).unwrap();assert!(db.migrate_lifecycle(&c).unwrap_err().contains("не совпадает"));assert_eq!(c.query_row("SELECT count(*) FROM study_bundles",[],|r|r.get::<_,i64>(0)).unwrap(),0);assert_eq!(c.query_row("SELECT count(*) FROM metadata WHERE key='lifecycle_v1'",[],|r|r.get::<_,i64>(0)).unwrap(),0);drop(c);clean(db)}
 #[test]fn deleted_and_changed_members_cannot_silently_change_printed_composition(){let db=fixture();let id=db.create_bundle(1,"Комплект",vec![1,2],10).unwrap();db.validate_bundle_print(id,1,vec![[1,1],[2,1]]).unwrap();db.set_study_deleted(1,1,true).unwrap();let removed=db.bundle(id).unwrap();assert_eq!(removed["studies"].as_array().unwrap().len(),2);assert_eq!(removed["canPrint"],false);assert!(db.validate_bundle_print(id,1,vec![[1,1],[2,1]]).is_err());db.set_study_deleted(1,2,false).unwrap();let changed=db.bundle(id).unwrap();assert_eq!(changed["canPrint"],true);assert!(!changed["issues"].as_array().unwrap().is_empty());assert!(db.validate_bundle_print(id,1,vec![[1,1],[2,1]]).is_err());db.validate_bundle_print(id,1,vec![[1,3],[2,1]]).unwrap();db.set_bundle_deleted(id,1,true).unwrap();assert_eq!(db.bundle(id).unwrap()["canPrint"],false);assert_eq!(db.study(1).unwrap()["status"],"final");assert!(db.set_bundle_deleted(id,1,false).is_err());db.set_bundle_deleted(id,2,false).unwrap();assert_eq!(db.bundle(id).unwrap()["canPrint"],true);assert_eq!(db.bundle(id).unwrap()["studies"].as_array().unwrap().len(),2);clean(db)}
 #[test]fn legacy_draft_composition_is_opened_without_applying_new_bundle_creation_rules(){let db=fixture();let c=db.open().unwrap();c.execute("UPDATE legacy_research SET protocol_id=6 WHERE id=1",[]).unwrap();db.migrate_lifecycle(&c).unwrap();let detail=db.bundle(1).unwrap();assert_eq!(detail["studies"][1]["id"],6);assert_eq!(detail["canPrint"],true);assert!(!detail["issues"].as_array().unwrap().is_empty());assert!(db.create_bundle(1,"Новый",vec![6,2],1).is_err());drop(c);clean(db)}
}
